#ifndef TPP_HAVE_LEXER_DUMP_DEFINITIONS_EXTRAINFO
#define TPP_HAVE_LEXER_DUMP_DEFINITIONS_EXTRAINFO (TPP_HAVE_LEXER_DUMP_DEFINITIONS)
#endif /* !TPP_HAVE_LEXER_DUMP_DEFINITIONS_EXTRAINFO */

